(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-l1"] = {"id":"x09-l1","patterns":["L1-venue","PARA-money","PARA-time","TR-printed","TR-spell","TR-selfcorrect","TR-price","TR-paraphrase"],"title":{"en":"Listening Part 1: booking a school visit","tr":"Listening Part 1: okul gezisi rezervasyonu","fa":"Listening Part 1: رزرو بازدید مدرسه"},"objective":{"en":"In this lesson you will learn to complete notes while a teacher books a group visit: follow the headings, choose the right price and rule for the group, and write only the missing word or number.","tr":"Bu derste bir öğretmen bir grup ziyareti için rezervasyon yaparken notları tamamlamayı öğreneceksin: başlıkları takip edecek, grup için doğru fiyatı ve kuralı seçecek ve yalnızca eksik kelimeyi ya da sayıyı yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک معلم بازدید گروهی رزرو می‌کند یادداشت‌ها را کامل کنی: عنوان‌ها را دنبال کنی، قیمت و قانون درستِ همان گروه را انتخاب کنی و فقط کلمه یا عددِ جاافتاده را بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: booking a school visit","tr":"Listening Part 1: okul gezisi rezervasyonu","fa":"Listening Part 1: رزرو بازدید مدرسه"},"objective":{"en":"In this lesson you will learn to complete notes while a teacher books a group visit: follow the headings, choose the right price and rule for the group, and write only the missing word or number.","tr":"Bu derste bir öğretmen bir grup ziyareti için rezervasyon yaparken notları tamamlamayı öğreneceksin: başlıkları takip edecek, grup için doğru fiyatı ve kuralı seçecek ve yalnızca eksik kelimeyi ya da sayıyı yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک معلم بازدید گروهی رزرو می‌کند یادداشت‌ها را کامل کنی: عنوان‌ها را دنبال کنی، قیمت و قانون درستِ همان گروه را انتخاب کنی و فقط کلمه یا عددِ جاافتاده را بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a class trip to a nature reserve","tr":"Bu sınav: bir doğa koruma alanına sınıf gezisi","fa":"این آزمون: اردوی کلاس به یک منطقه‌ی حفاظت‌شده"},"intro":{"en":"Part 1 is an everyday conversation in which one person needs information. Booking a venue or a group visit is a regular situation: the caller asks practical questions, and the details depend on who the group is.","tr":"Part 1, birinin bilgiye ihtiyaç duyduğu günlük bir konuşmadır. Bir mekân ya da grup ziyareti ayarlamak düzenli çıkan bir durumdur: arayan pratik sorular sorar ve ayrıntılar grubun kim olduğuna bağlıdır.","fa":"Part 1 یک گفتگوی روزمره است که در آن کسی به اطلاعات نیاز دارد. رزرو یک مکان یا بازدید گروهی موقعیتی است که مرتب می‌آید: تماس‌گیرنده سؤال‌های عملی می‌پرسد و جزئیات به این بستگی دارد که گروه چه کسانی‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-l1-ctx","exam":true,"patterns":["L1-venue","PARA-money","PARA-time"],"often":{"pattern":"L1-venue","n":3,"of":40,"label":{"en":"Comes up often in the real exam: 3 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 3’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۳ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Booking a school trip","tr":"Bir okul gezisi için rezervasyon","fa":"رزرو یک اردوی مدرسه"},"asks":{"en":"A teacher phones a place that runs school visits. First she asks about activities, prices, helpers, lunch and what to bring; then the officer explains the arrangements for the day and how to confirm the booking.","tr":"Bir öğretmen okul gezileri düzenleyen bir yeri arıyor. Önce etkinlikleri, fiyatları, refakatçileri, öğle yemeğini ve yanında ne getirileceğini soruyor; sonra görevli günün düzenlemelerini ve rezervasyonun nasıl kesinleşeceğini anlatıyor.","fa":"یک معلم به جایی زنگ می‌زند که اردوی مدرسه برگزار می‌کند. اول درباره‌ی فعالیت‌ها، قیمت، همراه‌ها، ناهار و وسایل لازم می‌پرسد؛ بعد مسئول آن‌جا برنامه‌ی روز و راه قطعی کردن رزرو را توضیح می‌دهد."},"fields":["Group size","Activities","Cost per child","Adult helpers","Lunch","What to bring","Where to park","Guide","Booking and deposit"],"words":[{"a":"per child","b":"for each pupil / a head","tr":"çocuk başına","fa":"برای هر بچه"},{"a":"reduced rate","b":"a cheaper price for local schools / a discount","tr":"indirimli fiyat","fa":"نرخ کاهش‌یافته"},{"a":"free","b":"come free / there’s no charge for","tr":"ücretsiz","fa":"رایگان"},{"a":"adult helpers","b":"parents / volunteers who come with the class","tr":"yetişkin refakatçiler","fa":"بزرگسال‌های همراه"},{"a":"if it rains","b":"if it’s wet / in bad weather","tr":"yağmur yağarsa","fa":"اگر باران بیاید"},{"a":"indoors","b":"somewhere dry / under cover","tr":"kapalı alanda","fa":"در فضای سرپوشیده"},{"a":"muddy","b":"wet and dirty ground","tr":"çamurlu","fa":"گِلی"},{"a":"meet","b":"be met by / be welcomed by","tr":"karşılanmak","fa":"استقبال شدن"},{"a":"souvenir","b":"something to take home / a small gift","tr":"hatıra eşyası","fa":"سوغاتی"},{"a":"confirm","b":"secure the date / make the booking definite","tr":"kesinleştirmek","fa":"قطعی کردن"},{"a":"deposit","b":"money paid in advance to hold a place","tr":"kapora, depozito","fa":"بیعانه"}],"traps":[{"en":"A general price, then a cheaper one for some groups: \"Normally it’s eight pounds, but members pay six.\" Check which group the caller is in.","tr":"Önce genel bir fiyat, sonra bazı gruplar için daha ucuzu: \"Normalde sekiz pound ama üyeler altı öder.\" Arayanın hangi grupta olduğuna bak.","fa":"اول یک قیمت کلی، بعد قیمتی ارزان‌تر برای بعضی گروه‌ها: «معمولاً هشت پوند است، اما اعضا شش می‌دهند». ببین تماس‌گیرنده در کدام گروه است."},{"en":"A rule for another group is corrected: \"...no, that’s for the older children.\" Write the rule for this caller.","tr":"Başka bir grubun kuralı düzeltilir: \"...yok, o büyük çocuklar için.\" Bu arayanın kuralını yaz.","fa":"قانونِ مربوط به گروه دیگری اصلاح می‌شود: «...نه، آن برای بچه‌های بزرگ‌تر است». قانونِ مربوط به همین تماس‌گیرنده را بنویس."},{"en":"A word next to the gap is already printed (\"___ hunt\", \"the ___ car park\"). Write only the missing word.","tr":"Boşluğun yanındaki kelime zaten yazılı (\"___ hunt\", \"the ___ car park\"). Yalnızca eksik kelimeyi yaz.","fa":"کلمه‌ی کنار جای خالی از قبل چاپ شده («___ hunt»، «the ___ car park»). فقط کلمه‌ی جاافتاده را بنویس."}],"example":{"lines":[["Officer","The talk is in the main hall."],["Teacher","Is that the big room by the entrance?"],["Officer","Ah, no, sorry, the main hall is being painted. This term we use the side hall, next to the café."]],"item":"The talk takes place in the ___ hall","answer":"side","why":{"en":"The main hall was the old answer. \"hall\" is printed, so write side.","tr":"Main hall eski cevaptı. \"hall\" yazılı, side yaz.","fa":"main hall جواب قبلی بود. «hall» چاپ شده، پس side را بنویس."}}},{"id":"L1-venue","ctx":["L1-venue","L1-volunteer"],"title":{"en":"Booking a venue or a group visit, volunteering","tr":"Bir mekân ya da grup ziyareti ayırtmak, gönüllülük","fa":"رزرو سالن یا بازدید گروهی، کار داوطلبانه"},"asks":{"en":"A teacher books a school visit, someone books a function room or a conference hotel, or a new volunteer gets the details. The notes collect numbers of people, rooms and equipment, food, times and tasks.","tr":"Bir öğretmen okul gezisi ayarlar, biri bir davet salonu ya da konferans oteli ayırtır ya da yeni bir gönüllü bilgi alır. Notlar kişi sayısını, salonları ve ekipmanı, yemeği, saatleri ve görevleri toplar.","fa":"معلمی یک بازدید مدرسه را رزرو می‌کند، کسی سالن مهمانی یا هتل همایش رزرو می‌کند، یا یک داوطلب تازه جزئیات را می‌گیرد. یادداشت‌ها تعداد نفرات، سالن و تجهیزات، غذا، ساعت‌ها و کارها را جمع می‌کنند."},"fields":["Date of visit or event","Number of people","Room / area","Equipment","Food and drink","Cost / deposit","Volunteer tasks","What to wear or bring"],"words":[{"a":"group","b":"the whole class / thirty of us","tr":"grup","fa":"گروه"},{"a":"capacity","b":"it holds up to","tr":"kapasite","fa":"ظرفیت"},{"a":"function room","b":"a room for parties","tr":"davet salonu","fa":"سالن مهمانی"},{"a":"catering","b":"the food / a buffet","tr":"yemek hizmeti","fa":"تهیه‌ی غذا"},{"a":"equipment","b":"a projector / a sound system","tr":"ekipman","fa":"تجهیزات"},{"a":"refreshments","b":"tea, coffee and biscuits","tr":"ikramlar","fa":"پذیرایی سبک"},{"a":"volunteer","b":"help without pay","tr":"gönüllü","fa":"داوطلب"},{"a":"tasks","b":"you'd be helping with / the job involves","tr":"görevler","fa":"کارها"},{"a":"accessible","b":"there's a ramp / easy for wheelchairs","tr":"engelli erişimine uygun","fa":"قابل دسترس برای ویلچر"},{"a":"supervise","b":"look after / keep an eye on","tr":"gözetmek","fa":"نظارت کردن"},{"a":"deposit","b":"pay part now to hold the date","tr":"kapora","fa":"بیعانه"},{"a":"outdoor","b":"outside / in the open air","tr":"açık havada","fa":"در فضای باز"}],"traps":[{"en":"Numbers of people change: \"about thirty... actually two classes, so fifty-six\".","tr":"Kişi sayısı değişir: \"yaklaşık otuz... aslında iki sınıf, yani elli altı\".","fa":"تعداد نفرات عوض می‌شود: «حدود سی نفر... راستش دو کلاس است، یعنی پنجاه‌وشش»."},{"en":"Equipment: the room \"already has\" some things; the caller asks for one more. The heading usually wants the extra one.","tr":"Ekipman: salonda bazı şeyler \"zaten var\"; arayan bir şey daha ister. Başlık genelde o ek şeyi ister.","fa":"تجهیزات: سالن بعضی چیزها را «از قبل دارد» و تماس‌گیرنده یک چیز دیگر می‌خواهد. عنوان معمولاً همان چیز اضافه را می‌خواهد."},{"en":"Volunteer tasks: one activity is mentioned and then ruled out for new volunteers.","tr":"Gönüllü görevleri: bir etkinlik söylenir, sonra yeni gönüllüler için elenir.","fa":"کارهای داوطلبانه: یک فعالیت گفته می‌شود و بعد برای داوطلب‌های تازه رد می‌شود."}],"example":{"lines":[["Manager","The garden room holds forty people."],["Caller","We’ll be about sixty."],["Manager","Then the main hall is better. It takes up to a hundred."],["Caller","Let’s book the main hall, then."]],"item":"Room booked: the main ___","answer":"hall","why":{"en":"The garden room is too small for sixty. They book the main hall.","tr":"Bahçe salonu altmış kişi için küçük. Ana salonu ayırtıyorlar.","fa":"سالن باغ برای شصت نفر کوچک است. سالن اصلی را رزرو می‌کنند."}},"general":true,"patterns":["L1-venue","L1-volunteer"],"often":{"pattern":"L1-venue","n":3,"of":40,"label":{"en":"Comes up often in the real exam: 3 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 3’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۳ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, two halves","tr":"On not, iki yarı","fa":"ده یادداشت، دو نیمه"},"body":{"en":"Questions 1-10 are one set of notes. Write ONE WORD AND/OR A NUMBER. There is a short pause after Question 5 to read the rest. The answers come in the same order as the notes, and you hear everything once.","tr":"Soru 1-10 tek bir not listesidir. ONE WORD AND/OR A NUMBER yaz. Kalanını okumak için Soru 5’ten sonra kısa bir ara vardır. Cevaplar notlarla aynı sırayla gelir ve her şeyi bir kez duyarsın.","fa":"سؤال‌های ۱ تا ۱۰ یک دسته یادداشت‌اند. ONE WORD AND/OR A NUMBER بنویس. بعد از سؤال ۵ یک مکث کوتاه برای خواندن بقیه هست. جواب‌ها به همان ترتیب یادداشت‌ها می‌آیند و همه‌چیز را یک بار می‌شنوی."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Before you listen, note who the caller is: a teacher, a local school, a group of children aged eight.","tr":"Dinlemeden önce arayanın kim olduğunu not et: bir öğretmen, yerel bir okul, sekiz yaşında çocuklardan oluşan bir grup.","fa":"قبل از گوش دادن یادداشت کن تماس‌گیرنده کیست: یک معلم، یک مدرسه‌ی محلی، گروهی از بچه‌های هشت‌ساله."},{"en":"For each gap, decide the type: price, number, place, thing, name.","tr":"Her boşluk için türüne karar ver: fiyat, sayı, yer, eşya, isim.","fa":"برای هر جای خالی نوعش را مشخص کن: قیمت، عدد، مکان، چیز، اسم."},{"en":"When you hear a price or a rule, wait: it may not apply to this group.","tr":"Bir fiyat ya da kural duyduğunda bekle: bu grup için geçerli olmayabilir.","fa":"وقتی قیمت یا قانونی می‌شنوی صبر کن: شاید مربوط به این گروه نباشد."},{"en":"Read the words next to the gap and write only what is missing.","tr":"Boşluğun yanındaki kelimeleri oku ve yalnızca eksik olanı yaz.","fa":"کلمه‌های کنار جای خالی را بخوان و فقط چیزی را بنویس که جا افتاده."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The rule for someone else","tr":"Başkası için olan kural","fa":"قانونِ مربوط به کس دیگر"},"body":{"en":"Venues have different rules for different groups: older children, members, local schools. The speaker often gives the wrong group’s rule first and then corrects it. Write the detail that fits this caller.","tr":"Mekânların farklı gruplar için farklı kuralları vardır: büyük çocuklar, üyeler, yerel okullar. Konuşan çoğu zaman önce yanlış grubun kuralını verir, sonra düzeltir. Bu arayana uyan bilgiyi yaz.","fa":"مکان‌ها برای گروه‌های مختلف قانون‌های مختلف دارند: بچه‌های بزرگ‌تر، اعضا، مدرسه‌های محلی. گوینده اغلب اول قانون گروه اشتباه را می‌گوید و بعد اصلاحش می‌کند. چیزی را بنویس که به همین تماس‌گیرنده می‌خورد."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Museum workshop · price per pupil: £___","lines":[["Officer","The workshop is four pounds a head."],["Teacher","Even for state schools?"],["Officer","Oh, sorry, no. State schools pay two fifty. Four pounds is for private groups."]],"answer":"2.50","walk":[{"en":"The caller is a state school, and the gap needs a price.","tr":"Arayan bir devlet okulu; boşluk bir fiyat istiyor.","fa":"تماس‌گیرنده یک مدرسه‌ی دولتی است و جای خالی قیمت می‌خواهد."},{"en":"Four pounds comes first, but \"sorry, no\" corrects it for this group.","tr":"Önce dört pound geliyor ama \"sorry, no\" bu grup için düzeltiyor.","fa":"اول چهار پوند می‌آید، اما «sorry, no» آن را برای این گروه اصلاح می‌کند."},{"en":"Write 2.50: \"£\" is printed.","tr":"2.50 yaz: \"£\" yazılı.","fa":"۲.۵۰ را بنویس: «£» چاپ شده."}]},"quick":{"prompt":"Notes: \"Bring a packed ___\". You hear: \"The café is closed on weekdays, so the children should bring a packed lunch.\" What do you write?","options":["packed lunch","lunch","café"],"correct":1,"why":{"en":"\"packed\" is printed before the gap, so write only lunch.","tr":"\"packed\" boşluktan önce yazılı; yalnızca lunch yaz.","fa":"«packed» قبل از جای خالی چاپ شده، پس فقط lunch را بنویس."}},"remember":{"en":"Know who the group is, wait for the rule that fits them, and never repeat a printed word.","tr":"Grubun kim olduğunu bil, onlara uyan kuralı bekle ve yazılı bir kelimeyi asla tekrarlama.","fa":"بدان گروه چه کسانی‌اند، منتظر قانونی بمان که به آن‌ها می‌خورد و هیچ‌وقت کلمه‌ی چاپ‌شده را تکرار نکن."},"type":"explain","id":"c-x09-l1-e","course":"ielts-exams","exam":"exam-09","unit":"x09-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"A school visit to Wexcombe Marshes","tr":"Wexcombe Marshes’a okul gezisi","fa":"بازدید مدرسه از وکسکام مارشز"},"timed":8,"ctx":["L1-venue"],"script":[{"who":"Kieran","line":"Good morning, Wexcombe Marshes Nature Reserve, education team. Kieran speaking."},{"who":"Joanne","line":"Oh, hello. My name's Joanne Pilling, and I teach Year Four at Brookfield Primary School. I'd like to book a visit for my class in the summer term."},{"who":"Kieran","line":"Lovely. How many children are there in the class?"},{"who":"Joanne","line":"Twenty-eight."},{"who":"Kieran","line":"That's fine, we can take up to thirty-two in one group. Now, for that age we usually recommend two activities. In the morning there's pond dipping, where the children use nets to catch and look at the creatures that live in the water. Then after lunch there's a bug hunt in the meadow and the woodland."},{"who":"Joanne","line":"They'll love that. Is the pond dipping safe, though? Some parents always worry about water."},{"who":"Kieran","line":"Completely. The dipping platforms have rails all round, and the water by the platforms is only knee-deep. One of our guides stays on each platform the whole time, and the children work in small teams."},{"who":"Joanne","line":"Good, I can tell them that. And what does it cost?"},{"who":"Kieran","line":"The standard charge is six pounds fifty per child. But you're in the county, aren't you?"},{"who":"Joanne","line":"Yes, we're about twenty minutes away."},{"who":"Kieran","line":"Then you qualify for the local schools rate, which is five pounds fifty. Teachers and helpers come free, of course."},{"who":"Joanne","line":"Great. How many adult helpers will I need?"},{"who":"Kieran","line":"Let me see. It's one adult for every six children... no, sorry, that's the rule for the older classes. For eight- and nine-year-olds it's one for every five, because of the water."},{"who":"Joanne","line":"One for every five. So with my teaching assistant and me, I'll need four parents as well."},{"who":"Kieran","line":"That's right."},{"who":"Joanne","line":"What happens about lunch? The children will bring packed lunches."},{"who":"Kieran","line":"On a fine day they can eat at the picnic tables by the lake. If it's wet, we open the barn for school groups, so there's always somewhere dry."},{"who":"Joanne","line":"That's a relief. Is there anything special they should bring?"},{"who":"Kieran","line":"The most important thing is boots. Even in summer the paths can be very muddy, and the children will be standing at the edge of the pond. Trainers just get soaked."},{"who":"Joanne","line":"Boots. I'll put that in the letter to parents."},{"who":"Kieran","line":"Now, a few things about the day itself. When your coach arrives, don't go to the main car park by the visitor centre. Coaches can't turn round there. Please use the lower car park, at the bottom of the hill."},{"who":"Joanne","line":"The lower car park. OK."},{"who":"Kieran","line":"Your group will be met there by one of our guides. For your date it'll be Sam Quarmby."},{"who":"Joanne","line":"Sorry, could you spell that?"},{"who":"Kieran","line":"Yes, it's Q-U-A-R-M-B-Y."},{"who":"Joanne","line":"Thank you. Is there anywhere the children can spend money? They always want a souvenir."},{"who":"Kieran","line":"There's a small shop in the visitor centre. Most things are a bit expensive for children, but we have badges with pictures of the reserve's birds, and they're only a pound each."},{"who":"Joanne","line":"Perfect. And how do I confirm the booking?"},{"who":"Kieran","line":"I'll send you a booking form. You can post it back, but it's much quicker if you send it by email, and then we can confirm the date straight away."},{"who":"Joanne","line":"Email's easier for me anyway."},{"who":"Kieran","line":"There's also a deposit of fifty pounds to secure the date. That needs to reach us by the fourteenth of March. After that we may give the date to another school."},{"who":"Joanne","line":"The fourteenth of March. I'll make sure the office pays it this week."},{"who":"Kieran","line":"Wonderful. I'll send the form this afternoon."},{"who":"Joanne","line":"Thanks so much, Kieran. Goodbye."}],"notes":{"title":"School visit to Wexcombe Marshes","headings":["Activities","Cost","Adults","Lunch","What to bring","On the day","Booking"]},"groups":[{"instruction":"Questions 1-10. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"note","questions":[{"n":1,"kind":"gap","prompt":"Activities · afternoon: ___ hunt in the meadow and woodland","accept":["bug"],"limit":1,"evidence":"there's a bug hunt in the meadow","why":{"en":"\"hunt\" is printed, so write one word: bug.","tr":"\"hunt\" yazılı, tek kelime yaz: bug.","fa":"«hunt» چاپ شده، پس یک کلمه بنویس: bug."},"trap":["TR-printed"]},{"n":2,"kind":"gap","prompt":"Cost · £___ per child (local schools)","accept":["5.50"],"limit":1,"evidence":"which is five pounds fifty","why":{"en":"£6.50 is the standard charge; county schools pay the local rate, 5.50.","tr":"6,50 £ normal ücret; ilçedeki okullar yerel fiyatı, 5,50 öder.","fa":"۶.۵۰ پوند قیمت عادی است؛ مدرسه‌های همان استان نرخ محلی یعنی ۵.۵۰ را می‌دهند."},"trap":["TR-price"]},{"n":3,"kind":"gap","prompt":"Adults · one helper for every ___ children","accept":["5","five"],"limit":1,"evidence":"it's one for every five","why":{"en":"\"One for every six\" is for older classes; for eight- and nine-year-olds it is five.","tr":"\"Her altı çocuğa bir\" büyük sınıflar için; sekiz dokuz yaşındakiler için beş.","fa":"«یک نفر برای هر شش بچه» مال کلاس‌های بزرگ‌تر است؛ برای بچه‌های هشت و نه ساله پنج است."},"trap":["TR-selfcorrect"]},{"n":4,"kind":"gap","prompt":"Lunch · if wet, eat in the ___","accept":["barn"],"limit":1,"evidence":"we open the barn for school groups","why":{"en":"Picnic tables on a fine day; \"if it’s wet, we open the barn\".","tr":"Güzel havada piknik masaları; \"yağmurluysa ambarı açıyoruz\".","fa":"در هوای خوب میزهای پیک‌نیک؛ «اگر بارانی باشد، انبار را باز می‌کنیم»."},"trap":["TR-paraphrase"]},{"n":5,"kind":"gap","prompt":"What to bring · children must have ___","accept":["boots"],"limit":1,"evidence":"The most important thing is boots","why":{"en":"\"The most important thing is boots\"; trainers \"just get soaked\".","tr":"\"En önemli şey çizme\"; spor ayakkabılar \"sırılsıklam olur\".","fa":"«مهم‌ترین چیز چکمه است»؛ کفش ورزشی «خیس آب می‌شود»."},"trap":["TR-paraphrase"]},{"n":6,"kind":"gap","prompt":"On the day · coach parks in the ___ car park","accept":["lower"],"limit":1,"evidence":"Please use the lower car park","why":{"en":"Not the main car park, where coaches cannot turn: \"the lower car park\". \"car park\" is printed.","tr":"Otobüslerin dönemediği ana otopark değil: \"alt otopark\". \"car park\" yazılı.","fa":"نه پارکینگ اصلی که اتوبوس نمی‌تواند دور بزند: «پارکینگ پایینی». «car park» چاپ شده."},"trap":["TR-printed","TR-ruledout"]},{"n":7,"kind":"gap","prompt":"On the day · guide: Sam ___","accept":["Quarmby"],"limit":1,"evidence":"Q-U-A-R-M-B-Y","why":{"en":"Spelled Q-U-A-R-M-B-Y: copy every letter, with a capital Q.","tr":"Q-U-A-R-M-B-Y diye harf harf: her harfi büyük Q ile kopyala.","fa":"حرف به حرف: Q-U-A-R-M-B-Y. همه‌ی حرف‌ها را با Q بزرگ بنویس."},"trap":["TR-spell"]},{"n":8,"kind":"gap","prompt":"On the day · shop: ___ for £1 each","accept":["badges"],"limit":1,"evidence":"we have badges with pictures of the reserve","why":{"en":"Most things are expensive, but the badges are a pound each. Plural.","tr":"Çoğu şey pahalı ama rozetler tanesi bir pound. Çoğul.","fa":"بیشتر چیزها گران‌اند، اما نشان‌ها هر کدام یک پوندند. جمع."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Booking · return the form by ___","accept":["email","e-mail"],"limit":1,"evidence":"it's much quicker if you send it by email","why":{"en":"Post is possible, but email is quicker and the teacher prefers it.","tr":"Posta mümkün ama e-posta daha hızlı ve öğretmen onu tercih ediyor.","fa":"پست هم می‌شود، اما ایمیل سریع‌تر است و معلم هم آن را ترجیح می‌دهد."},"trap":["TR-paraphrase"]},{"n":10,"kind":"gap","prompt":"Booking · deposit must arrive by ___ March","accept":["14","14th"],"limit":1,"evidence":"by the fourteenth of March","why":{"en":"\"By the fourteenth of March\": write 14.","tr":"\"On dört marta kadar\": 14 yaz.","fa":"«تا چهاردهم مارس»: ۱۴ را بنویس."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Kieran":{"accent":"Irish","gender":"M","tts":{"engine":"kokoro","voice":"bm_daniel","fallback":true,"note":"Irish wanted; no free Irish voice yet"},"role":"Education officer at a nature reserve"},"Joanne":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma"},"role":"Primary-school teacher booking a visit"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a telephone conversation between a teacher and a man who works at a nature reserve. First, you have some time to look at Questions 1 to 5."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-5"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 5."},{"type":"lines","from":0,"to":19,"note":"phone line: light telephone filter on Joanne; office ambience under Kieran"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 6 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 6-10"},{"type":"announcer","text":"Now listen and answer Questions 6 to 10."},{"type":"lines","from":20,"to":33},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x09-l1-d","course":"ielts-exams","exam":"exam-09","unit":"x09-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"An officer says you must pay a deposit \"to secure the date\". This means the money...","options":["keeps the date for you","is returned after the visit","pays for lunch"],"correct":0,"why":{"en":"To secure a date = to make sure nobody else can book it.","tr":"Bir tarihi secure etmek = başkasının o günü ayırtamamasını sağlamak.","fa":"secure کردن تاریخ یعنی مطمئن شوی کس دیگری آن روز را رزرو نمی‌کند."}},{"tests":"paraphrase","point":1,"prompt":"The notes say \"if wet\". Which words in a recording mean the same?","options":["if it’s busy","if it’s cold","if it rains"],"correct":2,"why":{"en":"Wet = rainy weather.","tr":"Wet = yağmurlu hava.","fa":"wet یعنی هوای بارانی."}},{"tests":"trap","point":3,"prompt":"Gap: \"Price for school groups: £___\". You hear: \"It’s twelve pounds per person, but schools pay nine.\" What do you write?","options":["12","9","21"],"correct":1,"why":{"en":"Twelve is the general price; the group asking is a school, so nine.","tr":"On iki genel fiyat; soran bir okul, yani dokuz.","fa":"دوازده قیمت عمومی است؛ گروهی که می‌پرسد مدرسه است، پس نه."}},{"tests":"method","point":2,"prompt":"Gap: \"Meet in the ___ hall\". You hear \"the sports hall\". What do you write?","options":["sports","sports hall","the sports hall"],"correct":0,"why":{"en":"\"hall\" is printed; write only the missing word.","tr":"\"hall\" yazılı; yalnızca eksik kelimeyi yaz.","fa":"«hall» چاپ شده؛ فقط کلمه‌ی جاافتاده را بنویس."}},{"tests":"method","point":2,"prompt":"Before Question 1, what is the most useful thing to note?","options":["the name of the person who answers","how long the call might be","who the group is and how old the children are"],"correct":2,"why":{"en":"Prices and rules often depend on the group, so knowing it helps you pick the right detail.","tr":"Fiyatlar ve kurallar çoğu zaman gruba bağlıdır; grubu bilmek doğru ayrıntıyı seçmeni sağlar.","fa":"قیمت‌ها و قانون‌ها اغلب به گروه بستگی دارند، پس دانستنش کمک می‌کند جزئیات درست را انتخاب کنی."}}],"id":"c-x09-l1-x","course":"ielts-exams","exam":"exam-09","unit":"x09-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
